{
  "findings": [
    {
      "check_id": "CKV_GCP_113",
      "title": "Ensure IAM policy should not define public access",
      "resource": "google_iam_workload_identity_pool_provider.pass2",
      "severity": "MEDIUM",
      "explanation": "The attribute_condition in this resource allows access to a specific repository and branch, which is good. However, it does not explicitly restrict public access. Adding a condition to ensure the issuer is trusted and matches the expected value will further secure the configuration."
    }
  ],
  "patched_code": "resource \"google_iam_workload_identity_pool_provider\" \"pass2\" {\n  workload_identity_pool_id          = \"example-pool\"\n  workload_identity_pool_provider_id = \"example-provider-2\"\n  attribute_mapping                 = {\n    \"google.subject\"       = \"assertion.sub\"\n  }\n  attribute_condition               = \"assertion.sub == 'repo:myOrg/myRepo:ref:refs/heads/main' && assertion.iss == 'https://token.actions.githubusercontent.com'\"\n  oidc {\n    issuer_uri                       = \"https://token.actions.githubusercontent.com\"\n  }\n}\n",
  "fix_summary": "Added a condition to the attribute_condition field to ensure the issuer matches the expected trusted value, further restricting access."
}
